/**
 * Interface texts (contracts/locales.md). Goes only through src/platform/i18n.ts
 * (principle VI); no visible text is hard-coded in src/ui/.
 */
import type { GeneratedI18nStructure } from '#i18n';
import { getMessage, getUILanguage } from '@/platform/i18n';
import type { ErrorCode } from '@/shared/errors';

/** Catalog keys, generated by @wxt-dev/i18n from src/locales/en.yml (`.wxt/i18n/`). */
export type MessageKey = keyof GeneratedI18nStructure;

export function t(key: MessageKey, substitutions?: string[]): string {
  return getMessage(key, substitutions);
}

export function errorMessage(code: ErrorCode): string {
  return t(`error.${code}`);
}

/** `fr` if the browser UI is in French (`fr`, `fr-CA`…), otherwise `en` (default language). */
export function uiLanguage(): 'en' | 'fr' {
  return getUILanguage().toLowerCase().startsWith('fr') ? 'fr' : 'en';
}

/**
 * ISO date (`2026-10-22`) according to the interface language: `22/10/2026` in French,
 * `22 October 2026` in English (month spelled out: no day/month ambiguity between British
 * and American usage, and no abbreviation varying from one browser to another). An invalid date is
 * rendered as is.
 */
export function formatDate(iso: string): string {
  const date = new Date(iso);
  if (!/^\d{4}-\d{2}-\d{2}/.test(iso) || Number.isNaN(date.getTime())) return iso;
  const options: Intl.DateTimeFormatOptions =
    uiLanguage() === 'fr' ? { timeZone: 'UTC' } : { timeZone: 'UTC', dateStyle: 'long' };
  return new Intl.DateTimeFormat(uiLanguage() === 'fr' ? 'fr-FR' : 'en-GB', options).format(date);
}
